#!/usr/bin/env python3
"""Author's solutions/scenes for the exact 2023 edition, exercises 413–429.

Printed pages 115–117 were visually read. Author checks are not an independent
review. Coordinates illustrate the proof; they are not offered as its evidence.
"""
import json
import math
from copy import deepcopy
from pathlib import Path

ROOT = Path(__file__).resolve().parents[2]
OUT = ROOT / 'geometry-course/textbook'
EX, MODELS = {}, []
BOOK = 'atanasyan-2023-7-9'
CHAPTER = '7-advanced'

def scene(points=(), segments=(), **kw):
    return dict(label=kw.pop('label', 'Условие'), points=list(points), segments=[list(s) for s in segments], **kw)
def tri(a='A', b='B', c='C'): return [[a,b],[b,c],[c,a]]
def update(v, **kw): return dict(deepcopy(v), **kw)
def arc(o,a,b,marks=0,radius=6): return dict(vertex=o, **{'from':a,'to':b}, marks=marks, radius=radius)
def eq(a,b,marks=1): return dict(a=a,b=b,marks=marks)
def right(a,o,b): return dict(a=a,vertex=o,b=b,size=2.6)
def ck(kind, **kw): return dict(type=kind, **kw)
def equal(*ss): return ck('equalLength',segments=[list(s) for s in ss])
def col(*ps): return ck('collinear',points=list(ps))
def perp(a,b,c,d): return ck('perpendicular',segments=[[a,b],[c,d]])
def ang(a,o,b,d): return ck('angle',points=[a,o,b],degrees=d)
def ratio(a,b,c,d,x): return ck('distanceRatio',segments=[[a,b],[c,d]],ratio=x)
def S(prompt, text, reason, refs): return (prompt,text,reason,refs if isinstance(refs,list) else [refs])
def unit(a,r=1): return (r*math.cos(math.radians(a)),r*math.sin(math.radians(a)))
def dist(a,b): return math.hypot(a[0]-b[0],a[1]-b[1])
def add(n,part,condition,answer,steps,p,base,views=None,cases=(),checks=(),givens=(),labels=None,notes=(),offsets=None,labelonly=()):
    pages=[115] if n<=414 else [116] if n<=426 else [117]
    vv={'neutral':deepcopy(base)}
    seq=views or [base]
    for i in range(len(steps)):
        vv[f'step-{i+1}']=deepcopy(seq[min(i,len(seq)-1)])
        vv[f'step-{i+1}']['label']=f'Шаг {i+1}'
    for i,v in enumerate(cases,1): vv[f'case-{i}']=deepcopy(v)
    xs,ys=zip(*p.values()); scale=min(76/(max(xs)-min(xs) or 1),48/(max(ys)-min(ys) or 1))
    cx=(min(xs)+max(xs))/2;cy=(min(ys)+max(ys))/2
    pp={k:[round(50+scale*(x-cx),9),round(35+scale*(y-cy),9),0] for k,(x,y) in p.items()}
    labs={k:k for k in p if not k.startswith('_')};labs.update(labels or {})
    m=dict(points=pp,edges=[],planar=True,bounds=[0,0,100,70],views=vv,
           checks=list(checks),labels=labs,labelOnly=list(labelonly),labelOffsets=offsets or {},
           description='Отдельный чертёж к задаче. Вспомогательные элементы вводятся по шагам; альтернативные случаи открываются отдельно.')
    item=dict(part=part,conditionSummary=condition,answer=answer,steps=[s[1] for s in steps],
              sourceVerified=True,mathVerified=True,
              visual=dict(initial='Данные условия; дополнительные построения скрыты.',
                          stepChanges=['Только построения и отметки текущего рассуждения.'],cases=[v['label'] for v in cases]))
    EX.setdefault(n,dict(number=n,printedPages=pages,pdfPages=[x+1 for x in pages],parts=[],notes=[]))['parts'].append(item)
    EX[n]['notes'].extend(notes)
    MODELS.append(dict(chapter=CHAPTER,collection='main',number=n,part=part,model=m,
                       didactics=dict(steps=[dict(prompt=s[0],justification=s[2],theoryPoints=s[3]) for s in steps]),
                       statementGivens=list(givens)))

# 413: exchange of the measuring unit.
p={'A':(0,2),'B':(6,2),'C':(0,0),'D':(2.5,0)}
b=scene('ABCD',[['A','B'],['C','D']])
add(413,'single','Длина AB при единице CD равна a, а длина CD при единице AB равна b. Установите связь между a и b.',
    'ab = 1, то есть b = 1/a и a = 1/b; оба числа положительны.',[
    S('Что означает число a при выбранной единице длины?','Если выразить обе длины в одной общей единице и обозначить их x и y, то a = x/y. Оба отрезка имеют положительную длину.','Числовая длина равна отношению длины отрезка к длине единицы.',[7,8]),
    S('Как записать число b в тех же обозначениях?','Теперь единицей служит AB, поэтому b = y/x.','Смена единицы измерения.',8),
    S('Что получится при умножении?','ab = (x/y)·(y/x) = 1. Поэтому a и b взаимно обратны. Равенство работает и когда один отрезок короче другого.','Сокращение ненулевых множителей.',7)],p,b,checks=[ratio('A','B','C','D',2.4)],
    givens=['a — длина AB в единицах CD.','b — длина CD в единицах AB.'])

# 414: two units for one segment.
p={'A':(0,3),'B':(6,3),'E1':(0,1.4),'F1':(2,1.4),'E2':(0,0),'F2':(1.2,0)}
b=scene(p,[['A','B'],['E1','F1'],['E2','F2']])
add(414,'single','Один и тот же отрезок AB имеет длину m в единицах E₁F₁ и длину n в единицах E₂F₂. Найдите длину E₁F₁ в единицах E₂F₂.',
    'n/m.',[
    S('Как связаны длины AB и двух единиц?','В любой общей единице измерения AB = m·E₁F₁ = n·E₂F₂. Числа m и n положительны.','Определение числовой длины.',[7,8]),
    S('Какое отношение требуется найти?','Искомое число — E₁F₁/E₂F₂. Из m·E₁F₁ = n·E₂F₂ разделим обе части на положительное m·E₂F₂.','Деление равенства на ненулевое число.',7),
    S('Проверьте порядок числителя и знаменателя.','Получаем E₁F₁/E₂F₂ = n/m. Например, если AB содержит 3 первых единицы и 5 вторых, то первая единица равна 5/3 второй.','Проверка смысла полученного отношения.',8)],p,b,
    checks=[ratio('A','B','E1','F1',3),ratio('A','B','E2','F2',5)],labels={'E1':'E₁','F1':'F₁','E2':'E₂','F2':'F₂'})

# 415: supplementary angles, explicit ray names in the source.
p={'O':(0,0),'H':unit(62,3),'K':(3,0),'L':(-3,0)}
b=scene('OHKL',rays=[['O','H'],['O','K'],['O','L']],angleArcs=[arc('O','K','H',0,9),arc('O','H','L',0,7)])
add(415,'single','Углы hk и hl смежные; угол hk меньше. Докажите: ∠hk = 90° − (∠hl − ∠hk)/2 и ∠hl = 90° + (∠hl − ∠hk)/2.',
    'Меньший угол равен 90° минус половина разности, больший — 90° плюс половина разности.',[
    S('Обозначьте углы и их разность.','Пусть α = ∠hk, β = ∠hl и d = β − α > 0. Так как углы смежные, α + β = 180°.','Свойство смежных углов.',11),
    S('Как получить удвоенный меньший угол?','Вычтем β − α = d из α + β = 180°: 2α = 180° − d. Значит, α = 90° − d/2.','Вычитание равенств.',11),
    S('Как получить удвоенный больший угол?','Сложим те же равенства: 2β = 180° + d. Значит, β = 90° + d/2. Подставив d = β − α, получаем обе формулы.','Сложение равенств.',11)],p,b,checks=[col('L','O','K'),ang('K','O','H',62)],labels={'H':'h','K':'k','L':'l'},
    givens=['h, k, l — лучи с общим началом O; k и l противоположны.'])

# 416: exactly the alternating five sectors of source figure 182.
angles=[0,25,55,110,130,180,205,235,290,310]
p={'O':(0,0),**{f'P{i}':unit(a,3) for i,a in enumerate(angles)}}
pairs=[(2,3),(0,1),(8,9),(6,7),(4,5)]
arcs=[arc('O',f'P{i}',f'P{j}',0,7) for i,j in pairs]
for k,(i,j) in enumerate(pairs,1):p[f'N{k}']=unit((angles[i]+angles[j])/2,2.8 if k==3 else 2.6)
p['N3u']=unit(120,2.6);p['N4u']=unit(40,2.6)
b=scene([f'N{k}' for k in range(1,6)],lines=[[f'P{i}',f'P{i+5}'] for i in range(5)],angleArcs=arcs)
first=update(b,points=['N1','N2','N3u','N4u','N5'],angleArcs=[arc('O','P0','P1',0,7),arc('O','P1','P2',0,7),arc('O','P2','P3',0,7),arc('O','P3','P4',0,7),arc('O','P4','P5',0,7)])
add(416,'single','Пять прямых проходят через одну точку. На рисунке 182 отмечены пять чередующихся углов 1, 2, 3, 4 и 5. Найдите их сумму.',
    '180°.',[
    S('Какие углы можно перенести в одну полуплоскость?','Оставим углы 1, 2 и 5 в верхней полуплоскости. Углы 3 и 4 заменим равными им вертикальными углами.','Вертикальные углы равны.',11),
    S('Что заполняют получившиеся пять углов?','Теперь пять углов стоят подряд между противоположными горизонтальными лучами: угол 2, вертикальный углу 4, угол 1, вертикальный углу 3 и угол 5. Вместе они составляют развёрнутый угол.','Пять прямых образуют десять последовательных секторов; выбранные сектора чередуются.',[4,11]),
    S('Какова искомая сумма?','Градусная мера развёрнутого угла равна 180°. Замена на вертикальные углы не изменила сумму, поэтому ∠1 + ∠2 + ∠3 + ∠4 + ∠5 = 180°.','Сложение градусных мер.',9)],p,b,[b,first,first],
    checks=[ang('P2','O','P3',55),ang('P0','O','P1',25),ang('P8','O','P9',20),ang('P6','O','P7',30),ang('P4','O','P5',50)],
    labels={**{f'N{i}':str(i) for i in range(1,6)},'N3u':'3','N4u':'4'},
    offsets={k:[0,0] for k in ['N1','N2','N3','N4','N5','N3u','N4u']},labelonly=['N1','N2','N3','N4','N5','N3u','N4u'],notes=['Чередование пяти углов сверено с рис. 182 точного издания.'])

# 417: counting intersections on one line, 5 = 2 + 3 is the only split.
p={'O':(0,0)}
for i,a in enumerate([0,27,58,90,122,153]):p[f'_u{i}']=unit(a,3);p[f'_v{i}']=unit(a+180,3)
p.update({'P':(-2,0),'Q':(2,0),'R':(2/3,8/3),'_l1':(-3,0),'_l2':(3,0),
          '_a':(1.5,3.5),'_b':(.5,-2.5),'_c':(0,4),'_d':(3.5,3),'_e':(4,1),
          'Ll':(-2.8,0),'La':(-.3,1.7),'Lb':(-.2,-1.8),'Lc':(.5,3),'Ld':(3,2),'Le':(3.8,.9)})
b=scene([],lines=[[f'_u{i}',f'_v{i}'] for i in range(6)],note='Шесть данных прямых. Буквы для рассуждения вводятся на шагах.')
line_names=['Ll','La','Lb','Lc','Ld','Le']
h1=scene(list('PQ')+line_names,lines=[['_l1','_l2'],['P','_a'],['P','_b'],['Q','_c'],['Q','_d'],['Q','_e']],note='Предположение для доказательства от противного: точки P и Q различны.')
h2=update(h1,points=list('PQR')+line_names,highlightSegments=[['P','R'],['Q','R']],note='В точке R проходят только две из шести прямых — противоречие условию.')
add(417,'single','Даны шесть попарно пересекающихся прямых. Через каждую точку пересечения любых двух проходит хотя бы ещё одна из этих прямых. Докажите, что все шесть проходят через одну точку.',
    'Все шесть прямых имеют общую точку.',[
    S('Выберите одну прямую l. Как на ней располагаются пересечения с пятью остальными?','В каждой такой точке встречаются хотя бы две из остальных пяти прямых. Поэтому эти пять прямых разбиваются на группы размером не меньше двух. Возможны только одна группа из пяти либо две группы: две и три прямые.','Каждая пара прямых имеет ровно одну точку пересечения.',1),
    S('Когда утверждение уже доказано?','Если группа одна, все пять прямых пересекают l в одной точке. Эта точка общая для всех шести прямых.','Определение общей точки прямых.',1),
    S('Предположите, что групп две. Как их обозначить?','Пусть через P на l проходят ещё a и b, а через другую точку Q — ещё c, d и e. Возьмём R = a ∩ c. Точка R существует, поскольку все прямые попарно пересекаются; R отлична от P и Q и не лежит на l.','Две различные прямые не имеют двух общих точек.',1),
    S('Может ли через R проходить третья прямая?','Прямая b уже встречает a в P, поэтому не проходит через R. Прямые d и e уже встречают c в Q, поэтому тоже не проходят через R. Прямая l через R не проходит. Значит, через R проходят только a и c — вопреки условию.','Единственность прямой через две точки; доказательство от противного.',[1,27]),
    S('Какой случай остаётся?','Разбиение 2 + 3 невозможно. Остаётся единственная группа из пяти, поэтому все шесть прямых пересекаются в одной точке.','Исключены все альтернативы.',27)],p,b,[b,b,update(h1,points=list('PQR')+line_names),h2,b],
    cases=[update(h2,label='Почему две разные точки невозможны',availableFromStep=4)],
    checks=[col('P','Q','_l1','_l2','Ll'),col('P','R','_a','La'),col('P','_b','Lb'),col('Q','R','_c','Lc'),col('Q','_d','Ld'),col('Q','_e','Le')],
    labels={k:k[1:] for k in line_names},labelonly=line_names,
    notes=['Контрпредположение показано отдельным видом и явно не выдаётся за конфигурацию, удовлетворяющую условию.'])

# 418: the point-line dual counting argument, no advanced theorem required.
p={c:(i-2.5,0) for i,c in enumerate('ABCDEF')}
p.update({'Ah':(0,0),'Bh':(2,0),'Ch':(4,0),'Dh':(1,2),'Eh':(2,4),'Fh':(3,6)})
b=scene('ABCDEF',lines=[['A','F']])
h=scene(['Ah','Bh','Ch','Dh','Eh','Fh'],lines=[['Ah','Ch'],['Ah','Fh']],note='Предположение: две различные прямые через A.')
h2=update(h,segments=[['Bh','Dh']],highlightSegments=[['Bh','Dh']],note='Прямая BD не содержит ни одной из остальных четырёх точек.')
add(418,'single','Даны шесть точек. Любая прямая через две из них содержит хотя бы ещё одну из этих шести точек. Докажите, что все шесть точек лежат на одной прямой.',
    'Все шесть точек коллинеарны.',[
    S('Выберите точку A и сгруппируйте остальные точки по прямым через A.','На каждой такой прямой, кроме A, находятся хотя бы две из оставшихся пяти точек. Поэтому возможны только одна группа из пяти либо две группы размером два и три.','Через две различные точки проходит ровно одна прямая.',1),
    S('Что означает одна группа?','Если группа одна, A и все остальные пять точек лежат на одной прямой. Это и требуется доказать.','Определение коллинеарных точек.',1),
    S('Почему две группы приводят к противоречию?','Пусть A, B, C лежат на одной прямой, а A, D, E, F — на другой. Рассмотрим BD. Она не содержит A. Она не содержит C, иначе прямые BC и BD совпали бы и D лежала бы на первой прямой.','Две различные прямые имеют не более одной общей точки.',1),
    S('Может ли BD содержать E или F?','Нет: прямая DE, как и DF, уже является второй прямой через A. Если бы B лежала на ней, обе исходные прямые имели бы общие A и B и совпали бы. Значит, на BD из шести точек лежат только B и D, что противоречит условию.','Единственность прямой через две точки.',1),
    S('Как завершить доказательство?','Случай двух групп исключён. Следовательно, группа одна и все шесть точек лежат на одной прямой.','Доказательство от противного.',27)],p,b,[b,b,h,h2,b],
    cases=[update(h2,label='Исключаем две разные прямые',availableFromStep=4)],
    checks=[col('A','B','C','D','E','F'),col('Ah','Bh','Ch'),col('Ah','Dh','Eh','Fh')],
    labels={c+'h':c for c in 'ABCDEF'},notes=['Изображение двух прямых — только контрпредположение, которое опровергается.'])

# 419: take the midpoint first; then use SAS and supplementary angles.
p={'A':(-2,0),'B':(2,0),'C1':(-.4,2.1),'C2':(.4,-2.1),'M':(0,0)}
b=scene(['A','B','C1','C2'],[['A','B'],['A','C1'],['B','C2'],['C1','C2']],equalSegments=[eq('A','C1'),eq('B','C2')],angleArcs=[arc('A','B','C1',1),arc('B','A','C2',1)])
v=update(b,points=['A','B','C1','C2','M'],equalSegments=b['equalSegments']+[eq('A','M',2),eq('B','M',2)])
add(419,'single','Точки C₁ и C₂ находятся по разные стороны от AB. Дано AC₁ = BC₂ и ∠BAC₁ = ∠ABC₂. Докажите, что C₁C₂ проходит через середину AB.',
    'Середина M отрезка AB лежит на прямой C₁C₂.',[
    S('Какую точку удобно ввести?','Обозначим середину AB через M. Тогда AM = BM, а лучи AM и AB совпадают; лучи BM и BA также совпадают.','Определение середины отрезка.',7),
    S('Какие треугольники равны по двум сторонам и углу?','В треугольниках AMC₁ и BMC₂ имеем AM = BM, AC₁ = BC₂ и ∠MAC₁ = ∠MBC₂. Поэтому эти треугольники равны по первому признаку.','Первый признак равенства треугольников.',15),
    S('Что это даёт для углов при M?','Получаем ∠AMC₁ = ∠BMC₂. При этом ∠AMC₁ + ∠C₁MB = 180°, поскольку MA и MB противоположны. Значит, ∠BMC₂ + ∠C₁MB = 180°.','Соответственные углы равных треугольников; смежные углы.',[15,11]),
    S('Почему C₁, M и C₂ лежат на одной прямой?','Точки C₁ и C₂ лежат по разные стороны от AB. Поэтому два последних угла примыкают друг к другу по разные стороны луча MB и дают развёрнутый угол C₁MC₂. Лучи MC₁ и MC₂ противоположны.','Развёрнутый угол и заданное расположение точек.',[4,11])],p,b,[v,v,v,v],
    checks=[equal(('A','C1'),('B','C2')),equal(('A','M'),('B','M')),col('A','M','B'),col('C1','M','C2')],labels={'C1':'C₁','C2':'C₂'})

# 420: extend the adjacent side by the length of the third side.
p={'A':(0,0),'B':(4,0),'C':(1,2)}
bc=dist(p['B'],p['C']);ac=dist(p['A'],p['C'])
p['D']=(1+bc/ac,2+2*bc/ac)
for k in ['A','B','C','D']:p[k+'1']=(p[k][0]+7,p[k][1])
b=scene(['A','B','C','A1','B1','C1'],tri()+tri('A1','B1','C1'),equalSegments=[eq('A','B'),eq('A1','B1')],angleArcs=[arc('A','B','C',1),arc('A1','B1','C1',1)])
v1=update(b,points=list(p),segments=tri()+tri('A1','B1','C1')+[['C','D'],['C1','D1']],equalSegments=b['equalSegments']+[eq('B','C',2),eq('C','D',2),eq('B1','C1',3),eq('C1','D1',3)])
v2=update(v1,segments=v1['segments']+[['B','D'],['B1','D1']])
add(420,'single','У двух треугольников соответственно равны угол, одна прилежащая к нему сторона и сумма двух остальных сторон. Докажите, что треугольники равны.',
    'Треугольники равны: данные позволяют восстановить равные углы при концах равной стороны.',[
    S('Как обозначить равные данные?','Пусть сравниваются ABC и A₁B₁C₁, где AB = A₁B₁, ∠A = ∠A₁ и AC + BC = A₁C₁ + B₁C₁.','Переименование вершин по соответствию данных.',14),
    S('Как превратить сумму сторон в один отрезок?','Продлим AC за C до D так, чтобы CD = CB. Аналогично построим D₁ за C₁ с C₁D₁ = C₁B₁. Тогда AD = AC + BC = A₁D₁. Проведём BD и B₁D₁.','Сложение длин на луче и откладывание равного отрезка.',[7,22]),
    S('Какие большие треугольники равны?','Треугольники ABD и A₁B₁D₁ равны по AB = A₁B₁, AD = A₁D₁ и равным углам при A и A₁. Значит, ∠ABD = ∠A₁B₁D₁ и ∠BDA = ∠B₁D₁A₁.','Первый признак равенства.',15),
    S('Как восстановить исходные углы при B и B₁?','Так как CD = CB, треугольник BCD равнобедренный: ∠CBD = ∠BDC = ∠BDA. Поэтому ∠ABC = ∠ABD − ∠BDA. Для второго треугольника получаем такую же разность равных углов. Значит, ∠ABC = ∠A₁B₁C₁.','Свойство углов при основании равнобедренного треугольника.',18),
    S('Какой признак завершает доказательство?','У исходных треугольников равны сторона AB и два прилежащих к ней угла: при A и при B. По второму признаку ABC и A₁B₁C₁ равны.','Второй признак равенства треугольников.',19)],p,b,[b,v2,v2,v2,b],
    checks=[col('A','C','D'),col('A1','C1','D1'),equal(('A','B'),('A1','B1')),equal(('A','D'),('A1','D1')),equal(('B','C'),('C','D')),equal(('B1','C1'),('C1','D1'))],
    labels={k+'1':k+'₁' for k in 'ABCD'},givens=['AB = A₁B₁; ∠A = ∠A₁.','AC + BC = A₁C₁ + B₁C₁.'])

# 421: equal sides need not occupy corresponding positions.
r=math.sqrt(8)
p={'A':(0,0),'B':(2,0),'C':(0,2),'D':(4,0),'E':(4+r,0),'F':(4,r)}
b=scene(p,tri()+tri('D','E','F'),rightAngles=[right('B','A','C'),right('E','D','F')])
v=update(b,equalSegments=[eq('B','C'),eq('D','E'),eq('D','F')])
add(421,'single','Сторона и два угла одного треугольника равны некоторой стороне и некоторым двум углам другого. Могут ли эти треугольники оказаться неравными?',
    'Да. Без указания соответствия равной стороны равным углам равенство треугольников не следует.',[
    S('Обязательно ли равная сторона лежит в одинаковом положении относительно равных углов?','Нет. В условии не сказано, что равные стороны заключены между соответствующими равными углами. Построим контрпример.','Точное содержание второго признака равенства.',19),
    S('Какие два треугольника удобно взять?','Возьмём прямоугольный равнобедренный ABC. Затем построим прямоугольный равнобедренный DEF, каждый катет которого равен гипотенузе BC первого. У обоих треугольников углы 45°, 45° и 90°.','Равнобедренный треугольник и сумма углов.',[18,31]),
    S('Почему данные выполнены, а треугольники не равны?','Сторона BC равна стороне DE, а две пары углов можно выбрать равными 45° и 90°. Но гипотенуза EF второго треугольника больше DE = BC, то есть больше наибольшей стороны первого. Треугольники не равны.','В прямоугольном треугольнике гипотенуза больше любого катета.',33)],p,b,[b,v,v],
    checks=[perp('A','B','A','C'),perp('D','E','D','F'),equal(('A','B'),('A','C')),equal(('D','E'),('D','F'),('B','C'))],
    givens=['Два прямоугольных равнобедренных треугольника.','В контрпримере BC = DE; равная сторона играет разную роль.'])

# 422: a genuine SSA ambiguity, even with corresponding side labels fixed.
p={'A':(0,0),'B':(6,0),'C':(3,math.sqrt(3)),'D':(6,2*math.sqrt(3))}
b=scene('ABC',tri(),angleArcs=[arc('A','B','C',0,7)])
v=scene('ABD',tri('A','B','D'),angleArcs=[arc('A','B','D',0,7)],rightAngles=[right('A','B','D')])
both=scene('ABCD',tri()+[['B','D'],['C','D']],equalSegments=[eq('B','C'),eq('B','D')],angleArcs=[arc('A','B','D',0,7)])
add(422,'single','Две стороны и угол одного треугольника равны некоторым двум сторонам и углу другого. Могут ли эти треугольники быть неравными?',
    'Да. Равный угол может лежать не между равными сторонами; тогда первый признак неприменим.',[
    S('Какое условие первого признака здесь отсутствует?','Не сказано, что равный угол заключён между равными сторонами. Покажем два неравных треугольника ABC и ABD с общей стороной AB, равными BC и BD и одним углом при A.','Первый признак требует угла между данными сторонами.',15),
    S('Как построить нужную конфигурацию?','Построим прямоугольный ABD с прямым углом B и углом A = 30°. На отрезке AD отметим C так, чтобы ∠ABC = 30°. Тогда в ABC углы A и B равны 30°, а угол C равен 120°.','Построение угла и сумма углов треугольника.',[22,31]),
    S('Почему BC = BD?','В BCD угол CBD равен 90° − 30° = 60°. Угол BDC равен углу BDA, то есть 60°. Третий угол тоже 60°, поэтому BCD равносторонний и BC = BD.','Сумма углов и признак равнобедренного треугольника.',[31,33]),
    S('Почему треугольники не равны?','У ABC есть угол 120°, а ABD прямоугольный. Следовательно, треугольники не равны, хотя AB — общая сторона, BC = BD и ∠BAC = ∠BAD = 30°.','Равные треугольники имеют равные углы.',14)],p,b,[b,both,both,both],
    cases=[update(v,label='Второй треугольник ABD',availableFromStep=2)],
    checks=[col('A','C','D'),equal(('B','C'),('B','D'),('C','D')),perp('A','B','B','D'),ang('B','A','C',30),ang('A','C','B',120)])

# 423: paired isosceles triangles and vertical angles.
p={'A':(-2,0),'B':(2,0),'O':(0,0),'C':(-1,-math.sqrt(3)),'D':(1,math.sqrt(3))}
b=scene('ABOCD',[['A','B'],['C','D'],['A','C'],['B','D']],equalSegments=[eq('A','C'),eq('A','O'),eq('B','O'),eq('B','D')])
v=update(b,angleArcs=[arc('O','A','C',1),arc('C','A','O',1),arc('O','B','D',1),arc('D','B','O',1)])
add(423,'single','Отрезки AB и CD пересекаются в O; AC = AO = BO = BD. Докажите OC = OD.',
    'OC = OD.',[
    S('Какие треугольники являются равнобедренными?','В ACO равны AC и AO, поэтому ∠ACO = ∠COA. В BDO равны BD и BO, поэтому ∠BDO = ∠DOB.','Свойство углов при основании.',18),
    S('Как связаны углы при O?','Углы COA и DOB вертикальные, значит, равны. Следовательно, равны также ∠ACO и ∠BDO.','Свойство вертикальных углов.',11),
    S('Как доказать равенство двух треугольников?','В ACO и BDO равны углы при O и C, D; значит, по сумме углов равны углы при A и B. Стороны AO и BO равны по условию. Поэтому треугольники равны по стороне и двум прилежащим углам.','Сумма углов и второй признак равенства.',[31,19]),
    S('Какие соответствующие стороны нужны?','В полученном соответствии A ↔ B, C ↔ D, O ↔ O. Поэтому OC = OD.','Соответственные стороны равных треугольников.',14)],p,b,[v,v,v,v],
    checks=[col('A','O','B'),col('C','O','D'),equal(('A','C'),('A','O'),('B','O'),('B','D')),equal(('O','C'),('O','D'))])

# 424: exterior bisectors at B and C meet at the excenter opposite A.
p={'A':(0,4),'B':(-3,0),'C':(3,0),'O':(0,-6),'_b':(-6,-4),'_c':(6,-4)}
b=scene('ABCO',tri()+[['B','O'],['C','O']],rays=[['B','_b'],['C','_c']],
        angleArcs=[arc('B','C','O',1,8),arc('B','O','_b',1,8),arc('C','B','O',2,7),arc('C','O','_c',2,7)])
add(424,'single','Прямые, содержащие биссектрисы внешних углов при B и C треугольника ABC, пересекаются в O. Найдите ∠BOC, если ∠A = α.',
    '∠BOC = 90° − α/2.',[
    S('Как выразить углы OBC и OCB?','Обозначим внутренние углы при B и C через β и γ. Биссектрисы внешних углов дают в треугольнике BOC углы ∠OBC = (180° − β)/2 и ∠OCB = (180° − γ)/2.','Смежные углы; определение биссектрисы.',[11,17]),
    S('Какова сумма β + γ?','В ABC имеем α + β + γ = 180°, поэтому β + γ = 180° − α.','Теорема о сумме углов.',31),
    S('Вычтите два угла треугольника BOC из 180°.','∠BOC = 180° − (90° − β/2) − (90° − γ/2) = (β + γ)/2 = 90° − α/2.','Сумма углов треугольника BOC.',31)],p,b,
    checks=[ang('C','B','O',math.degrees(math.atan2(6,3))),ang('B','C','O',math.degrees(math.atan2(6,3)))],
    givens=['O — пересечение прямых внешних биссектрис при B и C.','∠A = α.'])

# 425: the three external triangles have one common unordered angle triple.
A=(0,3);B=(-3,0);C=(4,0);a=dist(B,C);bb=dist(A,C);c=dist(A,B)
def excenter(wa,wb,wc):return tuple((wa*A[i]+wb*B[i]+wc*C[i])/(wa+wb+wc) for i in range(2))
p={'A':A,'B':B,'C':C,'X':excenter(a,bb,-c),'Y':excenter(-a,bb,c),'Z':excenter(a,-bb,c),'_I':excenter(a,bb,c)}
b=scene('ABC',tri(),lines=[['X','Z'],['X','Y'],['Y','Z']])
vx=scene('ABX',tri('A','B','X'),label='Треугольник ABX',availableFromStep=2)
vy=scene('BCY',tri('B','C','Y'),label='Треугольник BCY',availableFromStep=3)
vz=scene('CAZ',tri('C','A','Z'),label='Треугольник CAZ',availableFromStep=3)
add(425,'single','Через каждую вершину треугольника проведена прямая, перпендикулярная его биссектрисе. Вместе со сторонами эти прямые образуют три треугольника. Докажите, что их углы соответственно равны.',
    'У каждого из трёх треугольников один набор углов: 90° − A/2, 90° − B/2, 90° − C/2.',[
    S('Какие углы образует проведённая прямая со сторонами?','Прямая через A, перпендикулярная внутренней биссектрисе, является прямой внешней биссектрисы. Поэтому острые углы, которые её нужные лучи образуют со сторонами, равны 90° − A/2. Аналогично при B и C.','Биссектриса делит угол пополам; дополнение до прямого угла.',[12,17]),
    S('Рассмотрите треугольник на стороне AB.','Пусть X — пересечение двух проведённых прямых при A и B. В ABX углы при A и B равны 90° − A/2 и 90° − B/2. Тогда угол X равен (A + B)/2 = 90° − C/2.','Сумма углов треугольника; A + B + C = 180°.',31),
    S('Какие углы получаются на двух других сторонах?','Для BCY имеем углы 90° − B/2, 90° − C/2 и 90° − A/2. Для CAZ — 90° − C/2, 90° − A/2 и 90° − B/2.','То же рассуждение с перестановкой вершин.',31),
    S('Какое соответствие углов надо выбрать?','Сопоставим углы с одинаковыми выражениями. Во всех трёх треугольниках получается один и тот же набор, значит, углы соответственно равны. Равенство самих треугольников здесь не утверждается.','Равенство градусных мер.',9)],p,b,[b,vx,vy,vz],cases=[vx,vy,vz],
    checks=[col('X','A','Z'),col('X','B','Y'),col('Y','C','Z'),perp('A','_I','X','Z'),perp('B','_I','X','Y'),perp('C','_I','Y','Z')],
    givens=['A, B, C в формулах обозначают градусные меры исходных углов.','X, Y, Z — пересечения проведённых прямых вне исходного треугольника.'])

# 426: two independently stated sufficient conditions for an acute triangle.
for part in ['а','б']:
    p={'A':(0,4),'B':(-3,0),'C':(4,0)};b=scene('ABC',tri(),angleArcs=[arc('A','B','C'),arc('B','C','A'),arc('C','A','B')])
    if part=='а':
        condition='Определите вид треугольника, если сумма любых двух его углов больше 90°.'
        steps=[S('Как выразить третий угол через сумму двух?','Если α + β > 90°, то γ = 180° − (α + β) < 90°.','Сумма углов треугольника.',31),
               S('Почему вывод относится ко всем трём углам?','Условие выполнено для любой пары. Выбирая по очереди пары α, β; β, γ; α, γ, получаем γ < 90°, α < 90°, β < 90°.','Применение условия ко всем парам.',31),
               S('Как называется такой треугольник?','Все его углы острые, поэтому треугольник остроугольный. Равенства 90° быть не может: в условии строгое «больше».','Определение остроугольного треугольника.',32)]
    else:
        condition='Определите вид треугольника, если каждый его угол меньше суммы двух остальных.'
        steps=[S('Возьмите один угол α. Чему равна сумма остальных?','Сумма двух остальных углов равна 180° − α. Поэтому условие даёт α < 180° − α.','Сумма углов треугольника.',31),
               S('Что следует для α?','Перенесём α: 2α < 180°, откуда α < 90°. То же рассуждение применимо к каждому углу.','Равносильное преобразование неравенства.',31),
               S('Каков вид треугольника?','Все три угла меньше 90°, значит, треугольник остроугольный.','Определение вида треугольника по углам.',32)]
    add(426,part,condition,'Остроугольный треугольник.',steps,p,b,
        checks=[ang('B','A','C',81.86989764584403),ang('A','B','C',53.13010235415598),ang('A','C','B',45)])

# 427: compare opposite sides and angles in the two triangles formed by a median.
p={'B':(-3,0),'C':(3,0),'M':(0,0),'A':(1,4),'Ar':(1,math.sqrt(8)),'At':(1,1.8)}
b=scene('ABCM',tri()+[['A','M']],equalSegments=[eq('B','M'),eq('M','C')])
acute=update(b,label='AM больше половины BC',availableFromStep=2)
vr=scene(['Ar','B','C','M'],tri('Ar','B','C')+[['Ar','M']],equalSegments=[eq('B','M'),eq('M','C'),eq('Ar','M')],label='AM равно половине BC',availableFromStep=3)
vt=scene(['At','B','C','M'],tri('At','B','C')+[['At','M']],equalSegments=[eq('B','M'),eq('M','C')],label='AM меньше половины BC',availableFromStep=4)
add(427,'single','Докажите: угол при вершине, из которой проведена медиана, острый, прямой или тупой, если медиана соответственно больше, равна или меньше половины противоположной стороны.',
    'AM > BC/2 ⇒ ∠A < 90°; AM = BC/2 ⇒ ∠A = 90°; AM < BC/2 ⇒ ∠A > 90°.',[
    S('Как обозначить части угла при A?','Пусть AM — медиана, BM = CM = BC/2, α = ∠BAM, β = ∠MAC. Тогда ∠A = α + β. Рассмотрим ABM и ACM.','Определение медианы.',17),
    S('Что происходит, если AM больше BM и CM?','В ABM против большей стороны AM лежит больший угол B, значит, ∠B > α. В ACM аналогично ∠C > β. Поэтому ∠B + ∠C > ∠A. Но сумма трёх углов 180°, следовательно, ∠A < 90°.','Сравнение сторон и противолежащих углов.',[33,31]),
    S('Что происходит при AM = BM = CM?','Треугольники ABM и ACM равнобедренные: ∠B = α и ∠C = β. Получаем ∠B + ∠C = ∠A и 2∠A = 180°, то есть ∠A = 90°.','Углы при основании и сумма углов.',[18,31]),
    S('Что меняется, если AM меньше BM и CM?','Теперь в ABM угол B меньше α, а в ACM угол C меньше β. Значит, ∠B + ∠C < ∠A; отсюда ∠A > 90°. Все три случая доказаны.','Обратное сравнение сторон и углов.',[33,31])],p,b,[b,acute,vr,vt],cases=[acute,vr,vt],
    checks=[col('B','M','C'),equal(('B','M'),('M','C')),equal(('Ar','M'),('B','M')),ang('B','Ar','C',90)],labels={'Ar':'A','At':'A'})

# 428: construct an equilateral triangle on AC on the same side as B.
t50=math.tan(math.radians(50));t30=math.tan(math.radians(30));t10=math.tan(math.radians(10))
x=t10/(t30+t10)
p={'A':(.5,.5*t50),'B':(0,0),'C':(1,0),'M':(x,x*t30)}
ca=(p['A'][0]-1,p['A'][1]);co=math.cos(math.pi/3);si=math.sin(math.pi/3)
p['N']=(1+ca[0]*co-ca[1]*si,ca[0]*si+ca[1]*co)
b=scene('ABCM',tri()+[['B','M'],['C','M'],['A','M']],equalSegments=[eq('A','B'),eq('A','C')])
v1=update(b,points=list('ABCMN'),segments=b['segments']+[['A','N'],['C','N']],equalSegments=[eq('A','B'),eq('A','C'),eq('A','N'),eq('C','N')])
v2=update(v1,segments=v1['segments']+[['B','N']])
vfinal=update(b,equalSegments=[eq('A','C',2),eq('C','M',2)])
add(428,'single','В равнобедренном ABC с основанием BC угол BAC равен 80°. Внутри выбрана M так, что ∠MBC = 30° и ∠MCB = 10°. Найдите ∠AMC.',
    '70°.',[
    S('Какие углы исходного треугольника известны?','Так как AB = AC, углы B и C равны (180° − 80°)/2 = 50°. Поэтому ∠ACM = 50° − 10° = 40°.','Свойство равнобедренного треугольника и сумма углов.',[18,31]),
    S('Какое дополнительное построение поможет сравнить AC и CM?','Построим равносторонний ACN по ту же сторону от AC, что и B. Луч AN проходит внутри угла BAC и образует с AB угол 80° − 60° = 20°. Так как AB = AC = AN, треугольник ABN равнобедренный.','Построение равностороннего треугольника и равенство боковых сторон.',[22,18]),
    S('Какие углы получаются при B и C у точки N?','В ABN углы при B и N равны (180° − 20°)/2 = 80°. Следовательно, луч BN лежит по другую сторону BC, чем A, и ∠CBN = 80° − 50° = 30°. Из ∠ACN = 60° и ∠ACB = 50° получаем ∠BCN = 10°.','Сумма углов и положение внешнего равностороннего треугольника.',[31,18]),
    S('Какие два треугольника теперь равны?','Треугольники BCM и BCN имеют общую BC и равные прилежащие углы 30° и 10°. По второму признаку они равны, поэтому CM = CN = CA.','Второй признак равенства.',19),
    S('Найдите искомый угол в AMC.','В AMC равны CA и CM, а угол при C равен 40°. Углы при A и M равны (180° − 40°)/2 = 70°. Значит, ∠AMC = 70°.','Равнобедренный треугольник и сумма углов.',[18,31])],p,b,[b,v1,v2,v2,vfinal],
    checks=[equal(('A','B'),('A','C'),('A','N'),('C','N'),('C','M')),ang('B','A','C',80),ang('M','B','C',30),ang('M','C','B',10),ang('A','M','C',70),ang('N','B','C',30),ang('B','C','N',10)],
    givens=['AB = AC; ∠BAC = 80°.','∠MBC = 30°; ∠MCB = 10°; M внутри ABC.'],offsets={'M':[3,4],'N':[-4,0]})

# 429: use the elementary maximum-distance-on-a-segment lemma twice.
